import unittest
from candidate import circular_shift

class TestCircularShift(unittest.TestCase):
    def test_circular_shift_single_digit(self):
        self.assertEqual(circular_shift(1, 0), "1")

    def test_circular_shift_two_digits(self):
        self.assertEqual(circular_shift(12, 1), "21")

    def test_circular_shift_three_digits(self):
        self.assertEqual(circular_shift(123, 1), "312")

    def test_circular_shift_shift_more_than_digits(self):
        self.assertEqual(circular_shift(123, 4), "321")

    def test_circular_shift_zero_shift(self):
        self.assertEqual(circular_shift(123, 0), "123")

    def test_circular_shift_negative_shift(self):
        with self.assertRaises(TypeError):
            circular_shift(123, -1)

    def test_circular_shift_non_integer_x(self):
        with self.assertRaises(TypeError):
            circular_shift("123", 1)

    def test_circular_shift_non_integer_shift(self):
        with self.assertRaises(TypeError):
            circular_shift(123, "1")

    def test_circular_shift_none_x(self):
        with self.assertRaises(TypeError):
            circular_shift(None, 1)

    def test_circular_shift_none_shift(self):
        with self.assertRaises(TypeError):
            circular_shift(123, None)

if __name__ == '__main__':
    unittest.main()
